// Get the full analysed script text
const text = $json.output || $json.fields['Analysed script'];

// Telegram message limit
const MAX_LENGTH = 4000; // leave a bit of buffer

// Split into chunks
const chunks = [];
for (let i = 0; i < text.length; i += MAX_LENGTH) {
  chunks.push({ part: text.slice(i, i + MAX_LENGTH) });
}

// Return as separate items
return chunks;
